const express = require('express');
const bodyParser = require('body-parser');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3000;
const LOG_FILE = path.join(__dirname, 'logs', 'user_inputs.txt');

// Middleware
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));
app.use(express.static('public'));

// Ensure logs directory exists
if (!fs.existsSync(path.join(__dirname, 'logs'))) {
    fs.mkdirSync(path.join(__dirname, 'logs'));
}

// Route to handle user input
app.post('/log-input', (req, res) => {
    const userInput = req.body.userInput;
    const timestamp = new Date().toISOString();

    // Format the log entry
    const logEntry = `[${timestamp}] User Input: ${userInput}\n`;

    // Append to log file
    fs.appendFile(LOG_FILE, logEntry, (err) => {
        if (err) {
            console.error('Error writing to log file:', err);
            return res.status(500).json({ 
                success: false, 
                message: 'Failed to log input' 
            });
        }

        console.log('Input logged successfully');
        res.json({ 
            success: true, 
            message: 'Input logged successfully' 
        });
    });
});

// Route to retrieve logs
app.get('/get-logs', (req, res) => {
    fs.readFile(LOG_FILE, 'utf8', (err, data) => {
        if (err) {
            if (err.code === 'ENOENT') {
                return res.json({ logs: 'No logs yet' });
            }
            return res.status(500).json({ 
                success: false, 
                message: 'Failed to read logs' 
            });
        }
        res.json({ logs: data });
    });
});

// Start server
app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});
```

