  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory storage (replace with database in production)
const notes = new Map();
const userSessions = new Map();

// Note structure
class Note {
  constructor(id, title, content, userId) {
    this.id = id;
    this.title = title;
    this.content = content;
    this.userId = userId;
    this.version = 0;
    this.lastModified = Date.now();
    this.activeUsers = new Set();
  }
}

// WebSocket connection handling
io.on('connection', (socket) => {
  console.log(`User connected: ${socket.id}`);

  // User authentication and session setup
  socket.on('authenticate', (userData) => {
    userSessions.set(socket.id, {
      userId: userData.userId,
      username: userData.username
    });

    // Send existing notes to the user
    const userNotes = Array.from(notes.values())
      .filter(note => note.userId === userData.userId)
      .map(note => ({
        id: note.id,
        title: note.title,
        content: note.content,
        version: note.version,
        lastModified: note.lastModified
      }));

    socket.emit('initial-notes', userNotes);
  });

  // Join a specific note room for real-time collaboration
  socket.on('join-note', (noteId) => {
    socket.join(`note-${noteId}`);

    const note = notes.get(noteId);
    if (note) {
      note.activeUsers.add(socket.id);

      // Notify other users in the room
      socket.to(`note-${noteId}`).emit('user-joined', {
        userId: socket.id,
        activeUsers: note.activeUsers.size
      });
    }
  });

  // Leave note room
  socket.on('leave-note', (noteId) => {
    socket.leave(`note-${noteId}`);

    const note = notes.get(noteId);
    if (note) {
      note.activeUsers.delete(socket.id);

      socket.to(`note-${noteId}`).emit('user-left', {
        userId: socket.id,
        activeUsers: note.activeUsers.size
      });
    }
  });

  // Create new note
  socket.on('create-note', (data) => {
    const noteId = `note-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const userSession = userSessions.get(socket.id);

    const newNote = new Note(
      noteId,
      data.title || 'Untitled',
      data.content || '',
      userSession.userId
    );

    notes.set(noteId, newNote);

    socket.emit('note-created', {
      id: newNote.id,
      title: newNote.title,
      content: newNote.content,
      version: newNote.version,
      lastModified: newNote.lastModified
    });
  });

  // Real-time note updates with operational transformation
  socket.on('update-note', (data) => {
    const { noteId, content, title, version, operations } = data;
    const note = notes.get(noteId);

    if (!note) {
      socket.emit('error', { message: 'Note not found' });
      return;
    }

    // Version conflict resolution
    if (version !== note.version) {
      // Send current version back to client for reconciliation
      socket.emit('version-conflict', {
        noteId,
        serverVersion: note.version,
        serverContent: note.content,
        serverTitle: note.title
      });
      return;
    }

    // Apply updates
    if (title !== undefined) note.title = title;
    if (content !== undefined) note.content = content;
    note.version++;
    note.lastModified = Date.now();

    // Broadcast to all other users in the note room
    socket.to(`note-${noteId}`).emit('note-updated', {
      noteId,
      title: note.title,
      content: note.content,
      version: note.version,
      lastModified: note.lastModified,
      operations,
      updatedBy: socket.id
    });

    // Acknowledge to sender
    socket.emit('update-acknowledged', {
      noteId,
      version: note.version,
      lastModified: note.lastModified
    });
  });

  // Cursor position sharing for collaborative editing
  socket.on('cursor-position', (data) => {
    const { noteId, position, selection } = data;
    const userSession = userSessions.get(socket.id);

    socket.to(`note-${noteId}`).emit('remote-cursor', {
      userId: socket.id,
      username: userSession?.username,
      position,
      selection
    });
  });

  // Delete note
  socket.on('delete-note', (noteId) => {
    const note = notes.get(noteId);
    const userSession = userSessions.get(socket.id);

    if (note && note.userId === userSession.userId) {
      notes.delete(noteId);

      // Notify all users in the room
      io.to(`note-${noteId}`).emit('note-deleted', { noteId });

      socket.emit('delete-acknowledged', { noteId });
    }
  });

  // Disconnect handling
  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket.id}`);

    // Remove user from all active notes
    notes.forEach((note, noteId) => {
      if (note.activeUsers.has(socket.id)) {
        note.activeUsers.delete(socket.id);

        io.to(`note-${noteId}`).emit('user-left', {
          userId: socket.id,
          activeUsers: note.activeUsers.size
        });
      }
    });

    userSessions.delete(socket.id);
  });
});

