const sqlite3 = require('sqlite3').verbose();
const path = require('path');

const dbPath = process.env.DB_PATH || './database.sqlite';
const db = new sqlite3.Database(dbPath);

// Initialize database tables
function initDatabase() {
    db.serialize(() => {
        // Users table
        db.run(`
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE NOT NULL,
                password TEXT NOT NULL,
                email TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            )
        `);

        // Login attempts table
        db.run(`
            CREATE TABLE IF NOT EXISTS login_attempts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                success BOOLEAN NOT NULL,
                ip_address TEXT,
                user_agent TEXT,
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                failure_reason TEXT
            )
        `);

        console.log('Database initialized successfully');
    });
}

// Log login attempt
function logLoginAttempt(username, success, ipAddress, userAgent, failureReason = null) {
    return new Promise((resolve, reject) => {
        const query = `
            INSERT INTO login_attempts (username, success, ip_address, user_agent, failure_reason)
            VALUES (?, ?, ?, ?, ?)
        `;

        db.run(query, [username, success, ipAddress, userAgent, failureReason], function(err) {
            if (err) {
                reject(err);
            } else {
                resolve(this.lastID);
            }
        });
    });
}

// Get all login attempts
function getAllLoginAttempts(limit = 100) {
    return new Promise((resolve, reject) => {
        const query = `
            SELECT * FROM login_attempts 
            ORDER BY timestamp DESC 
            LIMIT ?
        `;

        db.all(query, [limit], (err, rows) => {
            if (err) {
                reject(err);
            } else {
                resolve(rows);
            }
        });
    });
}

// Get login attempts by username
function getLoginAttemptsByUsername(username) {
    return new Promise((resolve, reject) => {
        const query = `
            SELECT * FROM login_attempts 
            WHERE username = ? 
            ORDER BY timestamp DESC
        `;

        db.all(query, [username], (err, rows) => {
            if (err) {
                reject(err);
            } else {
                resolve(rows);
            }
        });
    });
}

// Get login statistics
function getLoginStats() {
    return new Promise((resolve, reject) => {
        const query = `
            SELECT 
                COUNT(*) as total_attempts,
                SUM(CASE WHEN success = 1 THEN 1 ELSE 0 END) as successful_logins,
                SUM(CASE WHEN success = 0 THEN 1 ELSE 0 END) as failed_logins,
                COUNT(DISTINCT username) as unique_users
            FROM login_attempts
        `;

        db.get(query, [], (err, row) => {
            if (err) {
                reject(err);
            } else {
                resolve(row);
            }
        });
    });
}

// User operations
function createUser(username, hashedPassword, email) {
    return new Promise((resolve, reject) => {
        const query = `INSERT INTO users (username, password, email) VALUES (?, ?, ?)`;

        db.run(query, [username, hashedPassword, email], function(err) {
            if (err) {
                reject(err);
            } else {
                resolve(this.lastID);
            }
        });
    });
}

function getUserByUsername(username) {
    return new Promise((resolve, reject) => {
        const query = `SELECT * FROM users WHERE username = ?`;

        db.get(query, [username], (err, row) => {
            if (err) {
                reject(err);
            } else {
                resolve(row);
            }
        });
