<?php
/**
 * Login Attempt Logger
 * Logs user login attempts to a flat file for later analysis
 */

class LoginLogger {
    private $logFile;
    private $logDirectory;

    /**
     * Constructor
     * @param string $logDirectory Directory where log files will be stored
     */
    public function __construct($logDirectory = 'logs') {
        $this->logDirectory = $logDirectory;

        // Create logs directory if it doesn't exist
        if (!file_exists($this->logDirectory)) {
            mkdir($this->logDirectory, 0755, true);
        }

        // Set log file name with date for easy rotation
        $this->logFile = $this->logDirectory . '/login_attempts_' . date('Y-m-d') . '.log';
    }

    /**
     * Log a login attempt
     * @param string $username Username attempting to login
     * @param bool $success Whether the login was successful
     * @param string $ipAddress IP address of the user
     * @param array $additionalData Any additional data to log
     * @return bool Success status
     */
    public function logAttempt($username, $success, $ipAddress = null, $additionalData = []) {
        // Get IP address if not provided
        if ($ipAddress === null) {
            $ipAddress = $this->getClientIP();
        }

        // Prepare log entry
        $logEntry = [
            'timestamp' => date('Y-m-d H:i:s'),
            'username' => $username,
            'success' => $success ? 'SUCCESS' : 'FAILED',
            'ip_address' => $ipAddress,
            'user_agent' => $_SERVER['HTTP_USER_AGENT'] ?? 'Unknown',
            'additional_data' => $additionalData
        ];

        // Format log entry as CSV for easy parsing
        $logLine = $this->formatLogEntry($logEntry);

        // Write to file
        return $this->writeToFile($logLine);
    }

    /**
     * Format log entry as CSV
     * @param array $logEntry Log entry data
     * @return string Formatted log line
     */
    private function formatLogEntry($logEntry) {
        // CSV format: timestamp, username, status, ip_address, user_agent, additional_data
        $fields = [
            $logEntry['timestamp'],
            $logEntry['username'],
            $logEntry['success'],
            $logEntry['ip_address'],
            str_replace(["\r", "\n", ","], " ", $logEntry['user_agent']),
            json_encode($logEntry['additional_data'])
        ];

        // Escape and quote fields
        $escapedFields = array_map(function($field) {
            return '"' . str_replace('"', '""', $field) . '"';
        }, $fields);

        return implode(',', $escapedFields) . PHP_EOL;
    }

    /**
     * Write log entry to file
     * @param string $logLine Formatted log line
     * @return bool Success status
     */
    private function writeToFile($logLine) {
        // Use file locking to prevent concurrent write issues
        $result = file_put_contents($this->logFile, $logLine, FILE_APPEND | LOCK_EX);

        if ($result === false) {
            error_log("Failed to write to login log file: " . $this->logFile);
            return false;
        }

        return true;
    }

    /**
     * Get client IP address
     * @return string IP address
     */
    private function getClientIP() {
        $ipKeys = [
            'HTTP_CLIENT_IP',
            'HTTP_X_FORWARDED_FOR',
            'HTTP_X_FORWARDED',
            'HTTP_X_CLUSTER_CLIENT_IP',
            'HTTP_FORWARDED_FOR',
            'HTTP_FORWARDED',
            'REMOTE_ADDR'
        ];

        foreach ($ipKeys as $key) {
            if (array_key_exists($key, $_SERVER)) {
                $ip = $_SERVER[$key];
                // Handle multiple IPs (take the first one)
                if (strpos($ip, ',') !== false) {
                    $ip = explode(',', $ip)[0];
                }
                $ip = trim($ip);
                if (filter_var($ip, FILTER_VALIDATE_IP)) {
                    return $ip;
                }
            }
        }

        return 'Unknown';
    }

    /**
     * Get log file path
     * @return string Log file path
     */
    public function getLogFilePath() {
        return $this->logFile;
    }

    /**
     * Read and parse log file
     * @param string $date Date in Y-m-d format (optional, defaults to today)
     * @return array Array of log entries
     */
    public function readLogs($date = null) {
        if ($date === null) {
            $date = date('Y-m-d');
        }

        $logFile = $this->logDirectory . '/login_attempts_' . $date . '.log';

        if (!file_exists($logFile)) {
            return [];
        }

        $logs = [];
        $handle = fopen($logFile, 'r');

        if ($handle) {
            while (($line = fgets($handle)) !== false) {
                $data = str_getcsv($line);
                if (count($data) >= 6) {
                    $logs[] = [
                        'timestamp' => $data[0],
                        'username' => $data[1],
                        'success' => $data[2],
                        'ip_address' => $data[3],
                        'user_agent' => $data[4],
                        'additional_data' => json_decode($data[5], true)
                    ];
                }
            }
            fclose($handle);
        }

        return $logs;
    }
}

