```

### 2. Frontend - JavaScript (app.js)

```javascript
// Wait for user consent
document.getElementById('allow-location').addEventListener('click', function() {
    requestLocation();
});

document.getElementById('deny-location').addEventListener('click', function() {
    document.getElementById('consent-banner').style.display = 'none';
    document.getElementById('content').style.display = 'block';
    showDefaultContent();
});

function requestLocation() {
    if ("geolocation" in navigator) {
        navigator.geolocation.getCurrentPosition(
            successCallback,
            errorCallback,
            {
                enableHighAccuracy: false,
                timeout: 5000,
                maximumAge: 300000 // Cache for 5 minutes
            }
        );
    } else {
        alert("Geolocation is not supported by your browser");
        showDefaultContent();
    }
}

function successCallback(position) {
    const locationData = {
        latitude: position.coords.latitude,
        longitude: position.coords.longitude,
        accuracy: position.coords.accuracy,
        timestamp: new Date().toISOString()
    };

    // Hide consent banner and show content
    document.getElementById('consent-banner').style.display = 'none';
    document.getElementById('content').style.display = 'block';

    // Send to backend
    sendLocationToServer(locationData);
}

function errorCallback(error) {
    console.error("Error getting location:", error.message);
    showDefaultContent();
}

async function sendLocationToServer(locationData) {
    try {
        const response = await fetch('/api/location', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(locationData)
        });

        const result = await response.json();
        displayLocalizedContent(result);
    } catch (error) {
        console.error('Error sending location:', error);
        showDefaultContent();
    }
}

function displayLocalizedContent(data) {
    document.getElementById('localized-content').innerHTML = `
        <h2>Content for ${data.region}</h2>
        <p>${data.localizedMessage}</p>
        <p>Local time: ${data.localTime}</p>
    `;
}

function showDefaultContent() {
    document.getElementById('localized-content').innerHTML = `
        <h2>Welcome!</h2>
        <p>Showing default content</p>
    `;
}
```

