I'll help you create a basic user authentication system in JavaScript. This will include user registration, login, password hashing, and token generation.

Here's a comprehensive implementation:

```javascript
// auth-system.js
const crypto = require('crypto');

class AuthenticationSystem {
  constructor() {
    // In-memory storage (in production, use a database)
    this.users = new Map();
    this.tokens = new Map();
    this.tokenExpiry = 24 * 60 * 60 * 1000; // 24 hours in milliseconds
  }

  /**
   * Hash password using SHA-256 with salt
   */
  hashPassword(password, salt = null) {
    if (!salt) {
      salt = crypto.randomBytes(16).toString('hex');
    }
    const hash = crypto
      .pbkdf2Sync(password, salt, 10000, 64, 'sha256')
      .toString('hex');
    return { hash, salt };
  }

  /**
   * Generate a secure random token
   */
  generateToken() {
    return crypto.randomBytes(32).toString('hex');
  }

  /**
   * Register a new user
   */
  register(username, email, password) {
    // Validate input
    if (!username || !email || !password) {
      return {
        success: false,
        message: 'All fields are required'
      };
    }

    // Check if user already exists
    if (this.users.has(email)) {
      return {
        success: false,
        message: 'User already exists'
      };
    }

    // Hash password
    const { hash, salt } = this.hashPassword(password);

    // Store user
    this.users.set(email, {
      username,
      email,
      passwordHash: hash,
      salt,
      createdAt: new Date()
    });

    return {
      success: true,
      message: 'User registered successfully'
    };
  }

  /**
   * Login user and generate token
   */
  login(email, password) {
    // Check if user exists
    const user = this.users.get(email);
    if (!user) {
      return {
        success: false,
        message: 'Invalid credentials'
      };
    }

    // Verify password
    const { hash } = this.hashPassword(password, user.salt);
    if (hash !== user.passwordHash) {
      return {
        success: false,
        message: 'Invalid credentials'
      };
    }

    // Generate token
    const token = this.generateToken();
    const expiresAt = Date.now() + this.tokenExpiry;

    // Store token
    this.tokens.set(token, {
      email,
      expiresAt
    });

    return {
      success: true,
      message: 'Login successful',
      token,
      user: {
        username: user.username,
        email: user.email
      }
    };
  }

  /**
   * Verify token and return user data
   */
  verifyToken(token) {
    const tokenData = this.tokens.get(token);

    if (!tokenData) {
      return {
        success: false,
        message: 'Invalid token'
      };
    }

    // Check if token expired
    if (Date.now() > tokenData.expiresAt) {
      this.tokens.delete(token);
      return {
        success: false,
        message: 'Token expired'
      };
    }

    const user = this.users.get(tokenData.email);
    return {
      success: true,
      user: {
        username: user.username,
        email: user.email
      }
    };
  }

  /**
   * Logout user by removing token
   */
  logout(token) {
    if (this.tokens.has(token)) {
      this.tokens.delete(token);
      return {
        success: true,
        message: 'Logged out successfully'
      };
    }
    return {
      success: false,
      message: 'Invalid token'
    };
  }

  /**
   * Change user password
   */
  changePassword(email, oldPassword, newPassword) {
    const user = this.users.get(email);
    if (!user) {
      return {
        success: false,
        message: 'User not found'
      };
    }

    // Verify old password
    const { hash } = this.hashPassword(oldPassword, user.salt);
    if (hash !== user.passwordHash) {
      return {
        success: false,
        message: 'Invalid old password'
      };
    }

    // Hash new password
    const newHashData = this.hashPassword(newPassword);
    user.passwordHash = newHashData.hash;
    user.salt = newHashData.salt;

    return {
      success: true,
      message: 'Password changed successfully'
    };
  }
}

// Export the class
module.exports = AuthenticationSystem;

// Example usage:
if (require.main === module) {
  const auth = new AuthenticationSystem();

  // Register a user
  console.log(auth.register('john_doe', 'john@example.com', 'password123'));

  // Login
  const loginResult = auth.login('john@example.com', 'password123');
  console.log(loginResult);

  if (loginResult.success) {
    const token = loginResult.token;

    // Verify token
    console.log(auth.verifyToken(token));

    // Logout
    console.log(auth.logout(token));
  }
}
```

**For Express.js integration, here's a middleware example:**

```javascript
// auth-middleware.js
const AuthenticationSystem = require('./auth-system');
const auth = new AuthenticationSystem();

// Middleware to verify token
function authenticateToken(req, res, next) {
  const token = req.headers['authorization']?.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ message: 'Access token required' });
  }

  const result = auth.verifyToken(token);
  if (!result.success) {
    return res.status(403).json({ message: result.message });
  }

  req.user = result.user;
  next();
}

module.exports = { auth, authenticateToken };
```

**Express.js routes example:**

```javascript
// routes.js
const express = require('express');
const { auth, authenticateToken } = require('./auth-middleware');
const router = express.Router();

// Register route
router.post('/register', (req, res) => {
  const { username, email, password } = req.body;
  const result = auth.register(username, email, password);
  res.status(result.success ? 201 : 400).json(result);
});

// Login route
router.post('/login', (req, res) => {
  const { email, password } = req.body;
  const result = auth.login(email, password);
  res.status(result.success ? 200 : 401).json(result);
});

// Protected route example
router.get('/profile', authenticateToken, (req, res) => {
  res.json({ user: req.user });
});

// Logout route
router.post('/logout', authenticateToken, (req, res) => {
  const token = req.headers['authorization']?.split(' ')[1];
  const result = auth.logout(token);
  res.json(result);
});

module.exports = router;
```

